INSERT INTO picture360_images (examId, specialty, conditionName, imageUrl, keyFeatures, examPearl, optionA, optionB, optionC, optionD, correctAnswer, explanation, status) VALUES
(1, 'ENT', 'Acoustic Neuroma', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ent_acoustic-neuroma-placeholder.webp', 'Unilateral sensorineural hearing loss (most common presenting symptom); tinnitus; unsteadiness; MRI shows enhancing mass at the cerebellopontine angle; may compress the trigeminal nerve causing facial numbness; facial nerve palsy is a late sign', 'Acoustic neuroma (vestibular schwannoma) is the most common cerebellopontine angle tumour. Unilateral sensorineural hearing loss is the most common presentation. MRI with gadolinium is the gold standard investigation. Bilateral acoustic neuromas are pathognomonic of neurofibromatosis type 2 (NF2)', 'Vestibular schwannoma at the cerebellopontine angle', 'Meniere disease', 'Otosclerosis', 'Cholesteatoma', 'A', 'Acoustic neuroma (vestibular schwannoma) is a benign tumour arising from Schwann cells of the vestibular nerve at the cerebellopontine angle. It presents with unilateral sensorineural hearing loss, tinnitus, and unsteadiness. MRI with gadolinium is the gold standard investigation. Treatment options include observation (watch and wait), stereotactic radiosurgery, or microsurgical excision. Bilateral acoustic neuromas are pathognomonic of neurofibromatosis type 2.', 'active'),
(1, 'ENT', 'Otosclerosis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ent_otosclerosis-placeholder.webp', 'Progressive conductive hearing loss, typically bilateral; onset in 20s-30s; family history common; Carhart notch on audiometry (dip at 2kHz on bone conduction); Schwartze sign (pink tinge behind the tympanic membrane from increased vascularity of the promontory)', 'Otosclerosis is the most common cause of conductive hearing loss in young adults with a normal tympanic membrane. It is caused by abnormal bone remodelling fixing the stapes footplate. It worsens during pregnancy. Treatment is hearing aids or stapedectomy. Carhart notch at 2kHz is characteristic on audiometry', 'Abnormal bone remodelling causing stapes fixation', 'Glue ear with middle ear effusion', 'Cholesteatoma eroding the ossicles', 'Tympanic membrane perforation', 'A', 'Otosclerosis is caused by abnormal bone remodelling that fixes the stapes footplate in the oval window, causing progressive conductive hearing loss. It typically presents in young adults (20s-30s), is more common in women, and may worsen during pregnancy. The tympanic membrane appears normal. Audiometry shows a conductive hearing loss with a characteristic Carhart notch at 2kHz. Treatment options are hearing aids or stapedectomy (surgical replacement of the stapes with a prosthesis).', 'active'),
(1, 'ENT', 'Parotid Gland Tumour', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ent_parotid-tumour-placeholder.webp', 'Painless swelling in the preauricular or infra-auricular region; slow-growing firm mass; facial nerve involvement (pain, facial weakness) suggests malignancy; most parotid tumours are benign; pleomorphic adenoma is the most common', 'Pleomorphic adenoma is the most common parotid tumour (80% of parotid tumours). Warthin tumour is the second most common and is bilateral in 10%. Facial nerve palsy with a parotid mass suggests malignancy (mucoepidermoid carcinoma is the most common malignant parotid tumour). Treatment is superficial parotidectomy with facial nerve preservation', 'Salivary gland neoplasm, most commonly pleomorphic adenoma', 'Parotid abscess', 'Mumps parotitis', 'Sjogren syndrome', 'A', 'Parotid gland tumours most commonly present as painless preauricular swellings. Pleomorphic adenoma accounts for 80% of parotid tumours and is benign. Warthin tumour (adenolymphoma) is the second most common. Facial nerve involvement (pain, weakness) suggests malignancy — mucoepidermoid carcinoma is the most common malignant parotid tumour. Investigation includes ultrasound and fine needle aspiration cytology. Treatment is superficial parotidectomy with facial nerve preservation.', 'active'),
(1, 'ENT', 'Submandibular Gland Stone', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ent_submandibular-stone-placeholder.webp', 'Recurrent painful swelling of the submandibular gland, worse during meals; palpable stone in the floor of the mouth along Wharton duct; may be visible on bimanual palpation; purulent discharge from the duct orifice if infected', 'Submandibular gland stones account for 80-90% of all salivary calculi because the saliva is more viscous and alkaline, and Wharton duct drains upward against gravity. 80% of submandibular stones are radio-opaque (visible on plain X-ray). Small stones may pass spontaneously; larger stones require surgical removal or sialoendoscopy', 'Salivary calculus causing obstructive sialadenitis', 'Submandibular gland tumour', 'Ludwig angina', 'Ranula', 'A', 'Submandibular gland stones (sialolithiasis) are the most common cause of salivary gland obstruction, accounting for 80-90% of all salivary calculi. They cause recurrent painful swelling of the gland, characteristically worse at mealtimes when saliva production increases. The stone may be palpable bimanually in the floor of the mouth. 80% are radio-opaque. Management includes hydration, sialogogues, and massage for small stones. Larger stones require surgical removal or sialoendoscopy.', 'active'),
(1, 'ENT', 'Ludwig''s Angina', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ent_ludwigs-angina-placeholder.webp', 'Bilateral submandibular space infection causing firm woody swelling of the floor of the mouth; elevated tongue; drooling; trismus; dysphagia; stridor indicates airway compromise; usually odontogenic in origin', 'Ludwig angina is a life-threatening bilateral submandibular space infection. Airway management is the immediate priority — it can cause rapid airway obstruction from tongue elevation. Most cases are odontogenic (dental infection). Treatment is IV antibiotics (co-amoxiclav plus metronidazole) and surgical drainage. Early anaesthetic assessment for airway is critical', 'Bilateral submandibular space infection threatening the airway', 'Peritonsillar abscess', 'Parapharyngeal abscess', 'Angioedema', 'A', 'Ludwig angina is a rapidly progressive bilateral cellulitis of the submandibular, sublingual, and submental spaces. It is most commonly odontogenic in origin. It causes firm woody swelling of the floor of the mouth, tongue elevation, drooling, and dysphagia. Airway compromise is the main danger and can occur rapidly. Management priorities are airway protection (early anaesthetic involvement), IV antibiotics (co-amoxiclav plus metronidazole), and surgical drainage if there is a collection.', 'active'),
(1, 'ENT', 'Laryngeal Carcinoma', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ent_laryngeal-carcinoma-placeholder.webp', 'Persistent hoarseness lasting more than 3 weeks (the cardinal symptom); stridor in advanced disease; dysphagia; referred otalgia; neck mass from cervical lymphadenopathy; weight loss; most are squamous cell carcinomas', 'Any patient with hoarseness persisting more than 3 weeks should be referred urgently for laryngoscopy under the 2-week wait pathway. Risk factors are smoking and alcohol (synergistic effect). Glottic tumours present early with hoarseness; supraglottic tumours present later with dysphagia or neck mass. Treatment depends on stage: radiotherapy for early disease, surgery for advanced', 'Squamous cell carcinoma of the larynx presenting with persistent hoarseness', 'Vocal cord polyp', 'Laryngopharyngeal reflux', 'Reinke oedema', 'A', 'Laryngeal carcinoma is predominantly squamous cell carcinoma, strongly associated with smoking and alcohol use. Persistent hoarseness for more than 3 weeks is the cardinal symptom and warrants urgent 2-week wait referral for laryngoscopy. Glottic tumours present early with hoarseness; supraglottic tumours present later with dysphagia, referred otalgia, or a neck mass. Treatment depends on staging: radiotherapy for early glottic tumours, laryngectomy with or without chemoradiotherapy for advanced disease.', 'active'),
(1, 'ENT', 'Sinusitis on imaging', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ent_sinusitis-placeholder.webp', 'Opacification or air-fluid levels in the paranasal sinuses on CT; mucosal thickening; maxillary sinuses most commonly affected; may show ostiomeatal complex obstruction; CT is the gold standard imaging for sinusitis', 'Acute sinusitis is usually viral and self-limiting. Antibiotics are only indicated if symptoms persist beyond 10 days or worsen after initial improvement. Amoxicillin is first-line. Complications include orbital cellulitis (from ethmoid sinusitis), frontal bone osteomyelitis (Pott puffy tumour), and intracranial abscess. CT sinuses is indicated for recurrent or complicated sinusitis', 'Paranasal sinus inflammation with mucosal thickening or air-fluid levels', 'Normal sinus anatomy', 'Nasal polyps on imaging', 'Sinonasal tumour', 'A', 'Sinusitis is inflammation of the paranasal sinuses, most commonly affecting the maxillary sinuses. CT is the gold standard imaging modality, showing mucosal thickening, opacification, or air-fluid levels. Acute sinusitis is usually viral and self-limiting; antibiotics (amoxicillin first-line) are indicated only if symptoms persist beyond 10 days or worsen after initial improvement. Complications include orbital cellulitis (from ethmoid sinusitis), Pott puffy tumour, and intracranial infection.', 'active'),
(1, 'ENT', 'Angiofibroma', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ent_angiofibroma-placeholder.webp', 'Unilateral nasal obstruction and recurrent severe epistaxis in an adolescent male; smooth lobulated vascular mass in the nasopharynx; CT/MRI shows Holman-Miller sign (anterior bowing of the posterior wall of the maxillary sinus); highly vascular tumour', 'Juvenile nasopharyngeal angiofibroma occurs almost exclusively in adolescent males. It is benign but locally aggressive and highly vascular. Biopsy is contraindicated due to risk of catastrophic haemorrhage. Diagnosis is clinical and radiological. Treatment is preoperative embolisation followed by surgical excision', 'Highly vascular benign tumour of the nasopharynx in adolescent males', 'Nasal polyp', 'Nasopharyngeal carcinoma', 'Inverted papilloma', 'A', 'Juvenile nasopharyngeal angiofibroma is a benign but locally aggressive highly vascular tumour occurring almost exclusively in adolescent males. It presents with unilateral nasal obstruction and recurrent severe epistaxis. CT shows the Holman-Miller sign (anterior bowing of the posterior maxillary sinus wall). Biopsy is contraindicated due to the risk of life-threatening haemorrhage. Treatment is preoperative embolisation to reduce vascularity followed by surgical excision.', 'active'),
(1, 'ENT', 'Zenker''s Diverticulum', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ent_zenker-diverticulum-placeholder.webp', 'Progressive dysphagia; regurgitation of undigested food; halitosis; gurgling in the throat; recurrent aspiration pneumonia; palpable swelling in the left side of the neck that may gurgle on palpation; typically affects elderly patients', 'Zenker diverticulum (pharyngeal pouch) is a posterior pulsion diverticulum through Killian dehiscence (between the thyropharyngeus and cricopharyngeus muscles). Barium swallow is the investigation of choice (NOT endoscopy first due to perforation risk). Treatment is endoscopic stapling or open surgical excision', 'Pharyngeal pouch through Killian dehiscence causing dysphagia and regurgitation', 'Oesophageal carcinoma', 'Achalasia', 'Globus pharyngeus', 'A', 'Zenker diverticulum (pharyngeal pouch) is a posterior pulsion diverticulum through Killian dehiscence between the thyropharyngeus and cricopharyngeus muscles. It typically affects elderly patients and presents with progressive dysphagia, regurgitation of undigested food, halitosis, and recurrent aspiration pneumonia. Barium swallow is the investigation of choice. Endoscopy should be performed cautiously due to perforation risk. Treatment is endoscopic stapling (Dohlman procedure) or open surgical excision.', 'active'),
(1, 'ENT', 'Periorbital Cellulitis from Sinusitis', 'https://d2xsxph8kpxj0f.cloudfront.net/310519663711071667/GhMhikMduyCUFy4jxiEHhk/ent_periorbital-cellulitis-sinus-placeholder.webp', 'Periorbital erythema and oedema in the context of acute sinusitis; may progress to orbital cellulitis with proptosis, ophthalmoplegia, and visual loss; Chandler classification grades severity from preseptal cellulitis to cavernous sinus thrombosis', 'Orbital complications are the most common complications of acute sinusitis, particularly ethmoid sinusitis in children. The Chandler classification: Grade I preseptal cellulitis, Grade II orbital cellulitis, Grade III subperiosteal abscess, Grade IV orbital abscess, Grade V cavernous sinus thrombosis. CT orbits and sinuses is mandatory if orbital cellulitis is suspected', 'Complication of sinusitis with periorbital or orbital infection', 'Allergic periorbital oedema', 'Dacryocystitis', 'Insect bite reaction', 'A', 'Periorbital and orbital cellulitis are the most common complications of acute sinusitis, particularly ethmoid sinusitis in children. The Chandler classification grades severity from preseptal cellulitis (Grade I) through orbital cellulitis, subperiosteal abscess, orbital abscess, to cavernous sinus thrombosis (Grade V). CT orbits and sinuses is mandatory if orbital involvement is suspected. Preseptal cellulitis is treated with oral antibiotics; orbital cellulitis requires IV antibiotics and possible surgical drainage.', 'active');
